import { Injectable, signal, computed } from '@angular/core';
import { ServiceDefinition } from '../models/service-definition.model';

const USER_SERVICES_KEY = 'dwsv_user_services';
const DELETED_DEFAULTS_KEY = 'dwsv_deleted_service_defaults';

/**
 * Manages CCL web service definitions.
 * Default services are loaded from config/defaults.json at app startup.
 * User services are persisted to localStorage and can override or extend defaults.
 */
@Injectable({ providedIn: 'root' })
export class ServiceRegistryService {
  private _defaultServices = signal<ServiceDefinition[]>([]);
  private _userServices = signal<ServiceDefinition[]>([]);
  private _deletedDefaults = signal<Set<string>>(new Set());

  /** Read-only access to default services for diff comparison */
  readonly defaultServices = this._defaultServices.asReadonly();

  /** All available services (defaults with user overrides applied + purely custom) */
  readonly allServices = computed(() => {
    const defaults = this._defaultServices();
    const userServices = this._userServices();
    const deleted = this._deletedDefaults();
    const userMap = new Map(userServices.map(s => [s.id, s]));

    const merged = defaults
      .filter(d => !deleted.has(d.id))
      .map(d => userMap.get(d.id) || d);

    const defaultIds = new Set(defaults.map(d => d.id));
    const custom = userServices.filter(s => !defaultIds.has(s.id));

    return [...merged, ...custom];
  });

  constructor() {
    this.loadFromStorage();
  }

  /** Called by app initializer after loading defaults.json */
  loadDefaults(services: ServiceDefinition[]): void {
    this._defaultServices.set(services);
  }

  /** Get a service by ID */
  getService(id: string): ServiceDefinition | undefined {
    return this.allServices().find(s => s.id === id);
  }

  /** Get the shipped default version of a service (ignoring user overrides) */
  getDefault(id: string): ServiceDefinition | undefined {
    return this._defaultServices().find(s => s.id === id);
  }

  /** Check if a service ID is from the defaults file */
  isDefault(id: string): boolean {
    return this._defaultServices().some(s => s.id === id);
  }

  /** Save/update a service definition to user storage */
  saveService(service: ServiceDefinition): void {
    this._userServices.update(services => {
      const idx = services.findIndex(s => s.id === service.id);
      if (idx >= 0) {
        const copy = [...services];
        copy[idx] = service;
        return copy;
      }
      return [...services, service];
    });
    this._deletedDefaults.update(set => {
      const copy = new Set(set);
      copy.delete(service.id);
      return copy;
    });
    this.saveToStorage();
  }

  /** Add a service (backward-compatible — skips if ID exists) */
  addService(service: ServiceDefinition): void {
    if (this.allServices().some(s => s.id === service.id)) return;
    this.saveService(service);
  }

  /** Update a service definition (backward-compatible) */
  updateService(id: string, updates: Partial<ServiceDefinition>): void {
    const existing = this.getService(id);
    if (!existing) return;
    this.saveService({ ...existing, ...updates, id });
  }

  /** Delete a service definition */
  deleteService(id: string): void {
    this._userServices.update(services => services.filter(s => s.id !== id));
    if (this.isDefault(id)) {
      this._deletedDefaults.update(set => new Set(set).add(id));
    }
    this.saveToStorage();
  }

  /** Remove a service (backward-compatible alias for deleteService) */
  removeService(id: string): void {
    this.deleteService(id);
  }

  /** Reset a default service — remove user version and deleted marker */
  resetService(id: string): void {
    this._userServices.update(services => services.filter(s => s.id !== id));
    this._deletedDefaults.update(set => {
      const copy = new Set(set);
      copy.delete(id);
      return copy;
    });
    this.saveToStorage();
  }

  /** Reset everything — clear all user data, revert to pure defaults */
  resetAll(): void {
    this._userServices.set([]);
    this._deletedDefaults.set(new Set());
    localStorage.removeItem(USER_SERVICES_KEY);
    localStorage.removeItem(DELETED_DEFAULTS_KEY);
    localStorage.removeItem('dwsv_service_registry');
  }

  /** Check if user has modified a default service */
  hasUserVersion(id: string): boolean {
    return this._userServices().some(s => s.id === id);
  }

  /** Get the set of deleted default service IDs */
  get deletedDefaults(): string[] {
    return [...this._deletedDefaults()];
  }

  /** Restore deleted defaults tracking from a saved bundle */
  restoreDeletedDefaults(ids: string[]): void {
    this._deletedDefaults.set(new Set(ids));
    this.saveToStorage();
  }

  /** Export only user-customized services (not merged with defaults) */
  exportUserServices(): ServiceDefinition[] {
    return this._userServices();
  }

  /** Export all service definitions as JSON */
  exportServices(): string {
    return JSON.stringify(this.allServices(), null, 2);
  }

  /** Import service definitions from JSON */
  importServices(json: string): { imported: number; skipped: number } {
    const services: ServiceDefinition[] = JSON.parse(json);
    this._userServices.set(services);
    this._deletedDefaults.set(new Set());
    this.saveToStorage();
    return { imported: services.length, skipped: 0 };
  }

  /** Replace all user services (for raw config editing) */
  replaceCustomServices(services: ServiceDefinition[]): void {
    this._userServices.set(services);
    this.saveToStorage();
  }

  private loadFromStorage(): void {
    try {
      const stored = localStorage.getItem(USER_SERVICES_KEY);
      if (stored) {
        this._userServices.set(JSON.parse(stored));
      } else {
        // Migration from old key
        const old = localStorage.getItem('dwsv_service_registry');
        if (old) {
          this._userServices.set(JSON.parse(old));
          this.saveToStorage();
          localStorage.removeItem('dwsv_service_registry');
        }
      }
    } catch { /* ignore parse errors */ }

    try {
      const stored = localStorage.getItem(DELETED_DEFAULTS_KEY);
      if (stored) {
        this._deletedDefaults.set(new Set(JSON.parse(stored)));
      }
    } catch { /* ignore parse errors */ }
  }

  private saveToStorage(): void {
    localStorage.setItem(USER_SERVICES_KEY, JSON.stringify(this._userServices()));
    localStorage.setItem(DELETED_DEFAULTS_KEY, JSON.stringify([...this._deletedDefaults()]));
  }
}
